import{_ as e,o as d,c as a,aj as o}from"./framework.js";const p=JSON.parse('{"title":"数据库 | Cms / Database | Documentation","description":"数据库分组用于管理站点内的多种数据存储：IndexedDB 动态表、表关系、键值存储，以及 SQLite / MySQL / SQL Server 外部表结构浏览与数据维护；SQL 日志 用于查看脚本与后台产生的 SQL 记录。脚本侧统一通过 k.DB 访问（SQLite 见 k.DB.sqlite）。","frontmatter":{"title":"数据库 | Cms / Database | Documentation","description":"数据库分组用于管理站点内的多种数据存储：IndexedDB 动态表、表关系、键值存储，以及 SQLite / MySQL / SQL Server 外部表结构浏览与数据维护；SQL 日志 用于查看脚本与后台产生的 SQL 记录。脚本侧统一通过 k.DB 访问（SQLite 见 k.DB.sqlite）。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/database/index.html"}]]},"headers":[],"relativePath":"zh/cms/database/index.md","filePath":"cms/database/index.md","lastUpdated":1780991406000}'),r={name:"zh/cms/database/index.md"};function s(l,t,i,n,c,h){return d(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="数据库" tabindex="-1">数据库 <a class="header-anchor" href="#数据库" aria-label="Permalink to &quot;数据库&quot;">​</a></h1><blockquote><p>菜单：左侧 <strong>数据库</strong> 分组（须在 <strong>编辑菜单</strong> 中勾选显示）<br> 路由前缀：<code>/_Admin/database/...?SiteId={站点GUID}</code></p></blockquote><p><strong>数据库</strong>分组用于管理站点内的多种数据存储：<strong>IndexedDB 动态表</strong>、表关系、<strong>键值存储</strong>，以及 <strong>SQLite / MySQL / SQL Server</strong> 外部表结构浏览与数据维护；<strong>SQL 日志</strong> 用于查看脚本与后台产生的 SQL 记录。脚本侧统一通过 <a href="/kb-docs/zh/api/database/">k.DB</a> 访问（SQLite 见 <a href="/kb-docs/zh/api/sqlite/">k.DB.sqlite</a>）。</p><div class="tip custom-block"><p class="custom-block-title">与内容（Content）的区别</p><table tabindex="0"><thead><tr><th></th><th><strong>数据库</strong></th><th><strong>内容 → 内容</strong></th></tr></thead><tbody><tr><td>模型</td><td>自定义表结构、KV、外部库表</td><td>内容类型 + 内容夹</td></tr><tr><td>典型用途</td><td>业务表、缓存键值、对接已有 SQL 库</td><td>页面可绑定的 CMS 条目</td></tr><tr><td>API</td><td><code>k.DB</code></td><td><code>k.content</code></td></tr></tbody></table><p>二者可配合使用，勿混为同一套建模。</p></div><div class="info custom-block"><p class="custom-block-title">高级菜单</p><p>数据库分组及子项在编辑菜单中标记为 <strong>advanced</strong>。未勾选时左侧不显示本分组。</p></div><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><ol><li>在 <a href="./../navigation.html#权限与编辑菜单">编辑菜单</a> 中勾选 <strong>数据库</strong> 及其需要的子项。</li><li>左侧展开 <strong>数据库</strong>。</li></ol><h2 id="子菜单-与后台顺序一致" tabindex="-1">子菜单（与后台顺序一致） <a class="header-anchor" href="#子菜单-与后台顺序一致" aria-label="Permalink to &quot;子菜单（与后台顺序一致）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>菜单</th><th>路径</th><th>权限（feature）</th><th>文档</th></tr></thead><tbody><tr><td>IndexedDB 表</td><td><code>/database/table</code></td><td><code>database</code></td><td><a href="./table.html">IndexedDB 表</a>（本篇）</td></tr><tr><td>IndexedDB 表关系</td><td><code>/database/table-relation</code></td><td><code>tableRelation</code></td><td><a href="./table-relation.html">表关系</a></td></tr><tr><td>键值存储</td><td><code>/database/key-value</code></td><td><code>keyValue</code></td><td><a href="./key-value.html">键值存储</a></td></tr><tr><td>SQLite 表</td><td><code>/database/sqlite-table</code></td><td><code>database</code></td><td><a href="./sqlite-table.html">SQLite 表</a></td></tr><tr><td>MySQL 表</td><td><code>/database/mysql-table</code></td><td><code>database</code></td><td><a href="./mysql-table.html">MySQL 表</a></td></tr><tr><td>SQL Server 表</td><td><code>/database/sqlserver-table</code></td><td><code>database</code></td><td><a href="./sqlserver-table.html">SQL Server 表</a></td></tr><tr><td>SQL 日志</td><td><code>/database/sql-logs</code></td><td><code>database·log</code></td><td><a href="./sql-logs.html">SQL 日志</a></td></tr></tbody></table><h3 id="开发参考-kscript-api" tabindex="-1">开发参考（KScript API） <a class="header-anchor" href="#开发参考-kscript-api" aria-label="Permalink to &quot;开发参考（KScript API）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>菜单</th><th>API 文档</th></tr></thead><tbody><tr><td>IndexedDB 表</td><td><a href="/kb-docs/zh/api/indexed-db/">k.DB.indexedDb</a></td></tr><tr><td>SQLite / MySQL / SQL Server 表</td><td><a href="/kb-docs/zh/api/database/">k.DB</a> · <a href="/kb-docs/zh/api/sqlite/">k.DB.sqlite</a></td></tr><tr><td>键值存储</td><td><a href="/kb-docs/zh/api/database/">k.DB</a>（KV 接口，详见子篇）</td></tr><tr><td>SQL 日志</td><td>只读观测，无独立 <code>k.*</code> CRUD</td></tr></tbody></table><h2 id="无侧栏菜单的编辑路由" tabindex="-1">无侧栏菜单的编辑路由 <a class="header-anchor" href="#无侧栏菜单的编辑路由" aria-label="Permalink to &quot;无侧栏菜单的编辑路由&quot;">​</a></h2><p>以下页面从表列表进入，面包屑仍归属对应表类型菜单（<code>dbType</code> 查询参数决定高亮 <strong>IndexedDB / SQLite / MySQL / SQL Server</strong>）：</p><table tabindex="0"><thead><tr><th>路由</th><th>说明</th></tr></thead><tbody><tr><td><code>/database/table/columns</code></td><td>编辑表字段（列定义）</td></tr><tr><td><code>/database/table/data</code></td><td>浏览、筛选表数据</td></tr><tr><td><code>/database/table/edit-data</code></td><td>新建或编辑单条数据</td></tr></tbody></table><p>深链示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/_Admin/database/table/columns?SiteId={站点GUID}&amp;id={表Id}&amp;dbType=IndexedDb</span></span>
<span class="line"><span>/_Admin/database/table/data?SiteId={站点GUID}&amp;id={表Id}&amp;dbType=Sqlite</span></span></code></pre></div><p><code>dbType</code> 取值与后台一致（如 <code>IndexedDb</code>、<code>Sqlite</code>、<code>Mysql</code>、<code>SqlServer</code>），以地址栏为准。</p><h2 id="建议阅读顺序" tabindex="-1">建议阅读顺序 <a class="header-anchor" href="#建议阅读顺序" aria-label="Permalink to &quot;建议阅读顺序&quot;">​</a></h2><p>若从站点数据建模入手，常见顺序为：</p><ol><li><strong><a href="./table.html">IndexedDB 表</a></strong> — 站点内默认动态表</li><li><strong><a href="./table-relation.html">表关系</a></strong> — 多表关联（依赖已有 IndexedDB 表）</li><li><strong><a href="./key-value.html">键值存储</a></strong> — 简单 KV</li><li><strong>SQLite / MySQL / SQL Server</strong> — 按项目是否接入外部库选读</li><li><strong><a href="./sql-logs.html">SQL 日志</a></strong> — 排障与审计</li></ol><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./../navigation.html">站点后台菜单总览</a></td><td>完整菜单树</td></tr><tr><td><a href="./../development/">开发</a></td><td>Code 中调用 <code>k.DB</code></td></tr><tr><td><a href="/kb-docs/zh/api/database/">k.DB</a></td><td>脚本 API</td></tr><tr><td><a href="/kb-docs/zh/api/sqlite/">k.DB.sqlite</a></td><td>SQLite 查询与表操作</td></tr></tbody></table>`,22)])])}const S=e(r,[["render",s]]);export{p as __pageData,S as default};
